template.css:
.alf-probability-display {
  background: #1a1a2e;
  border: 2px solid #ff88ff;
  border-radius: 12px;
  padding: 20px;
}
.prob-header {
  margin-bottom: 20px;
  padding-bottom: 15px;
  border-bottom: 2px solid #ff88ff;
}
.prob-title {
  color: #ff88ff;
  font-size: 1.3em;
  font-weight: bold;
}
.prob-cards {
  display: flex;
  flex-direction: column;
  gap: 15px;
}
.prob-card {
  background: #0a0a0a;
  border-radius: 8px;
  padding: 15px;
  border: 2px solid #333;
}
.prob-card.alzheimers {
  border-color: #ff0044;
}
.prob-card.autism {
  border-color: #00ccff;
}
.prob-card.normal {
  border-color: #00ff88;
}
.prob-card-header {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 10px;
}
.prob-icon {
  font-size: 1.5em;
}
.prob-label {
  font-weight: bold;
  color: #fff;
  font-size: 1.1em;
}
.prob-value {
  font-size: 2.5em;
  font-weight: bold;
  margin: 10px 0;
  text-align: center;
}
.prob-card.alzheimers .prob-value {
  color: #ff0044;
}
.prob-card.autism .prob-value {
  color: #00ccff;
}
.prob-card.normal .prob-value {
  color: #00ff88;
}
.prob-bar {
  height: 30px;
  background: #222;
  border-radius: 15px;
  overflow: hidden;
  margin: 10px 0;
}
.prob-bar-fill {
  height: 100%;
  transition: width 0.5s ease;
  display: flex;
  align-items: center;
  justify-content: center;
  font-weight: bold;
  color: #000;
}
.prob-bar-fill.alzheimers {
  background: linear-gradient(90deg, #ff0044, #ff4488);
}
.prob-bar-fill.autism {
  background: linear-gradient(90deg, #00ccff, #44eeff);
}
.prob-bar-fill.normal {
  background: linear-gradient(90deg, #00ff88, #44ffaa);
}
.prob-note {
  font-size: 0.75em;
  color: #888;
  text-align: center;
  margin-top: 8px;
}

template.js:
function initAlfProbabilityDisplay(element, config) {
  function updateProbabilities(data) {
    // Update Alzheimer's
    if (data.alzheimers !== undefined) {
      const alzValue = Math.round(data.alzheimers);
      element.querySelector('#' + config.id + '-alz-value').textContent = alzValue + '%';
      element.querySelector('#' + config.id + '-alz-bar').style.width = alzValue + '%';
    }

    // Update Autism
    if (data.autism !== undefined) {
      const autValue = Math.round(data.autism);
      element.querySelector('#' + config.id + '-aut-value').textContent = autValue + '%';
      element.querySelector('#' + config.id + '-aut-bar').style.width = autValue + '%';
    }

    // Update Normal
    if (data.normal !== undefined) {
      const normValue = Math.round(data.normal);
      element.querySelector('#' + config.id + '-norm-value').textContent = normValue + '%';
      element.querySelector('#' + config.id + '-norm-bar').style.width = normValue + '%';
    }
  }

  return { updateProbabilities };
}
